export interface SeedCategory {
  name: string;
  image: string;
  order: number;
}

export interface SeedBanner {
  eyebrow: string;
  title: string;
  description: string;
  ctaText: string;
  image: string;
  mobileImage?: string;
  badgeText: string;
  link: string;
  order: number;
  active: boolean;
}

export interface SeedReview {
  customerName: string;
  location: string;
  comment: string;
  rating: number;
  avatar: string;
  productName: string;
  order: number;
  featured: boolean;
}

export interface SeedVariant {
  name: string;
  mrp: number;
  price: number;
  quantity: number;
  discount?: number;
}

export interface SeedProduct {
  _id?: string;
  name: string;
  description: string;
  image: string;
  mrp: number;
  price: number;
  discount: number;
  quantity: number;
  gst: number;
  isTaxable: boolean;
  category: string;
  rating: number;
  reviewsCount: number;
  variants: SeedVariant[];
}

